import React, { Component } from "react";

class Reglages extends Component {
  render() {
    //On récupère les données de l'API
    const { data } = this.props;
    if (!data) return null;

    //On parcoure l'arborescence jusqu'a la branche stop_date_time et on sélectionne departure_date_time
    const {end_production_date} = data.regions[0]
    const current_datetime = data.context
    const timezone = data.context
    return (
      <div>
          <end_production_date/>
          {current_datetime}
          {timezone}
      </div>
    )
  }
}

export default Reglages;
